'use strict';

// MODULES //

var path = require( 'node:path' );
var fs = require( 'node:fs' );
var Ajv2020 = require( 'ajv/dist/2020' ).default;


// VARIABLES //

var schemaDirectory = path.resolve( __dirname, './../../../../../schemas' );
var files = {
	'registry-v1': 'registry/v1.schema.json',
	'compliance-v1': 'compliance/v1.schema.json',
	'stored-record-v1': 'stored-record/v1.schema.json',
	'data-index-v1': 'data-index/v1.schema.json'
};
var ajv = new Ajv2020( {
	'allErrors': true,
	'strict': false,
	'formats': {
		'uri': true
	}
} );
var validators = new Map();

Object.keys( files ).forEach( function compile( name ) {
	var schema = JSON.parse( fs.readFileSync( path.join( schemaDirectory, files[ name ] ), 'utf8' ) );
	validators.set( name, ajv.compile( schema ) );
} );


// FUNCTIONS //

/**
* Formats schema errors for a bounded diagnostic.
*
* @private
* @param {Array} errors - Ajv errors
* @returns {string} diagnostic
*/
function formatErrors( errors ) {
	return ( errors || [] ).slice( 0, 12 ).map( function format( error ) {
		return ( error.instancePath || '/' ) + ' ' + error.message;
	} ).join( '; ' );
}


// MAIN //

/**
* Asserts that a value satisfies a local JSON Schema.
*
* @param {string} name - validator name
* @param {*} value - value to validate
* @throws {Error} if validation fails
*/
function assertSchema( name, value ) {
	var validator = validators.get( name );

	if ( !validator ) {
		throw new Error( 'Unknown local schema validator: ' + name );
	}
	if ( !validator( value ) ) {
		throw new Error( name + ' validation failed: ' + formatErrors( validator.errors ) );
	}
}


// EXPORTS //

module.exports = assertSchema;
